:root {
  color-scheme: light;
  --canvas: var(--rhoe-canvas, #eef1ed);
  --surface: var(--rhoe-surface, #fcfdfb);
  --surface-muted: var(--rhoe-surface-muted, #e2e6e1);
  --text: var(--rhoe-text, #191b19);
  --text-secondary: var(--rhoe-text-secondary, #59605b);
  --border: var(--rhoe-border, #d9ddd9);
  --primary: var(--rhoe-primary, #252725);
  --primary-hover: var(--rhoe-primary-hover, #343734);
  --primary-foreground: var(--rhoe-primary-foreground, #f8faf8);
  --success: var(--rhoe-success, #18794e);
  --success-foreground: var(--rhoe-success-foreground, #ffffff);
  --success-surface: var(--rhoe-success-surface, #e7f6ec);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #17653f);
  --warning: var(--rhoe-warning, #946200);
  --warning-foreground: var(--rhoe-warning-foreground, #ffffff);
  --warning-surface: var(--rhoe-warning-surface, #fff3d6);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #6b4600);
  --danger: var(--rhoe-danger, #b42318);
  --danger-foreground: var(--rhoe-danger-foreground, #ffffff);
  --danger-surface: var(--rhoe-danger-surface, #fce8e6);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #8f1d14);
  --focus: var(--rhoe-focus, #3f6652);
  --radius-surface: 18px;
  --shadow-resting: 0 1px 2px rgb(20 28 23 / 5%), 0 10px 30px rgb(20 28 23 / 6%);
  --shadow-floating: 0 4px 12px rgb(20 28 23 / 8%), 0 24px 48px rgb(20 28 23 / 12%);
  --duration-fast: 160ms;
  --duration-standard: 280ms;
  --duration-considered: 480ms;
  --duration-reveal: 600ms;
  --duration-expand: 720ms;
  --ease-enter: cubic-bezier(0.16, 1, 0.3, 1);
  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --input-expanded-duration: var(--duration-considered);
  --input-expanded-ease: var(--ease-enter);
}

@media (prefers-color-scheme: dark) {
  :root:not([data-theme]) {
    color-scheme: dark;
    --canvas: var(--rhoe-canvas, #121412);
    --surface: var(--rhoe-surface, #1a1d1a);
    --surface-muted: var(--rhoe-surface-muted, #232623);
    --text: var(--rhoe-text, #f1f3f0);
    --text-secondary: var(--rhoe-text-secondary, #afb5b0);
    --border: var(--rhoe-border, #373b37);
    --primary: var(--rhoe-primary, #ecefeb);
    --primary-hover: var(--rhoe-primary-hover, #ffffff);
    --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
    --success: var(--rhoe-success, #62c98f);
    --success-foreground: var(--rhoe-success-foreground, #092416);
    --success-surface: var(--rhoe-success-surface, #173526);
    --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
    --warning: var(--rhoe-warning, #e9ad45);
    --warning-foreground: var(--rhoe-warning-foreground, #291900);
    --warning-surface: var(--rhoe-warning-surface, #3b2b12);
    --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
    --danger: var(--rhoe-danger, #ff716b);
    --danger-foreground: var(--rhoe-danger-foreground, #260503);
    --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
    --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
    --focus: var(--rhoe-focus, #93b7a2);
    --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
    --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
  }
}

html[data-theme="light"] {
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --canvas: var(--rhoe-canvas, #121412);
  --surface: var(--rhoe-surface, #1a1d1a);
  --surface-muted: var(--rhoe-surface-muted, #232623);
  --text: var(--rhoe-text, #f1f3f0);
  --text-secondary: var(--rhoe-text-secondary, #afb5b0);
  --border: var(--rhoe-border, #373b37);
  --primary: var(--rhoe-primary, #ecefeb);
  --primary-hover: var(--rhoe-primary-hover, #ffffff);
  --primary-foreground: var(--rhoe-primary-foreground, #1b1d1b);
  --success: var(--rhoe-success, #62c98f);
  --success-foreground: var(--rhoe-success-foreground, #092416);
  --success-surface: var(--rhoe-success-surface, #173526);
  --success-surface-foreground: var(--rhoe-success-surface-foreground, #8ee0ae);
  --warning: var(--rhoe-warning, #e9ad45);
  --warning-foreground: var(--rhoe-warning-foreground, #291900);
  --warning-surface: var(--rhoe-warning-surface, #3b2b12);
  --warning-surface-foreground: var(--rhoe-warning-surface-foreground, #f2c66f);
  --danger: var(--rhoe-danger, #ff716b);
  --danger-foreground: var(--rhoe-danger-foreground, #260503);
  --danger-surface: var(--rhoe-danger-surface, #3d1d1c);
  --danger-surface-foreground: var(--rhoe-danger-surface-foreground, #ffaaa5);
  --focus: var(--rhoe-focus, #93b7a2);
  --shadow-resting: 0 1px 2px rgb(0 0 0 / 20%), 0 14px 34px rgb(0 0 0 / 22%);
  --shadow-floating: 0 6px 16px rgb(0 0 0 / 32%), 0 28px 56px rgb(0 0 0 / 40%);
}

::selection {
  background: color-mix(in srgb, var(--focus) 24%, transparent);
}

html[data-theme="dark"] .rhoe-code-source .shiki,
html[data-theme="dark"] .rhoe-code-source .shiki span {
  color: var(--shiki-dark) !important;
}

@media (prefers-color-scheme: dark) {
  html:not([data-theme="light"]) .rhoe-code-source .shiki,
  html:not([data-theme="light"]) .rhoe-code-source .shiki span {
    color: var(--shiki-dark) !important;
  }
}

@keyframes rhoe-input-value-error-feedback {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-4px); }
  50% { transform: translateX(3px); }
  75% { transform: translateX(-2px); }
}

@keyframes rhoe-input-value-error-feedback-reduced {
  0%, 100% { opacity: 1; }
  50% { opacity: 0.55; }
}

@keyframes rhoe-input-character-reveal {
  from { opacity: 0; transform: translateY(100%); }
  to { opacity: 1; transform: translateY(0%); }
}

@keyframes rhoe-calendar-range-reveal {
  from { clip-path: inset(0 100% 0 0); }
  to { clip-path: inset(0 0 0 0); }
}

export const motionTokens = {
  duration: {
    instant: 0.12,
    fast: 0.16,
    standard: 0.24,
    considered: 0.48,
    reveal: 0.6,
    expand: 0.72,
    lineReveal: 0.86,
  },
  ease: {
    enter: [0.16, 1, 0.3, 1],
    standard: [0.22, 1, 0.36, 1],
  },
  spring: {
    snappy: { type: "spring", visualDuration: 0.26, bounce: 0.12 },
    smooth: { type: "spring", visualDuration: 0.4, bounce: 0 },
    morph: { type: "spring", visualDuration: 0.42, bounce: 0.16 },
  },
  stagger: { item: 0.035, character: 0.025, word: 0.075, line: 0.08 },
  blur: { subtle: 2 },
} as const;

"use client";

import {
  forwardRef,
  useId,
  useImperativeHandle,
  useRef,
  useState,
  type CSSProperties,
  type ComponentPropsWithoutRef,
  type ReactNode,
} from "react";
import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { motionTokens } from "../lib/motion-tokens";
import "../foundation.css";

export interface VerificationCodeProps
  extends Omit<ComponentPropsWithoutRef<"input">, "children" | "defaultValue" | "maxLength" | "onChange" | "size" | "type" | "value"> {
  length?: number;
  value?: string;
  defaultValue?: string;
  label?: ReactNode;
  hint?: string;
  error?: ReactNode;
  onValueChange?: (value: string) => void;
  onComplete?: (value: string) => void;
}

function digitsOnly(value: string, length: number) {
  return value.replace(/\D/g, "").slice(0, length);
}

export const VerificationCode = forwardRef<HTMLInputElement, VerificationCodeProps>(
  function VerificationCode({
    id,
    length = 6,
    value,
    defaultValue = "",
    label = "Verification code",
    hint,
    error,
    disabled,
    required,
    className,
    onValueChange,
    onComplete,
    onFocus,
    onBlur,
    ...props
  }, forwardedRef) {
    const generatedId = useId();
    const inputId = id ?? generatedId;
    const hintId = `${inputId}-hint`;
    const errorId = `${inputId}-error`;
    const inputRef = useRef<HTMLInputElement>(null);
    const safeLength = Math.max(1, Math.floor(length));
    const [internalValue, setInternalValue] = useState(() => digitsOnly(defaultValue, safeLength));
    const [focused, setFocused] = useState(false);
    const [caret, setCaret] = useState<number | null>(null);
    const reduceMotion = useReducedMotion() ?? false;
    const currentValue = digitsOnly(value ?? internalValue, safeLength);
    const activeIndex = Math.min(caret ?? currentValue.length, safeLength - 1);
    const describedBy = [props["aria-describedby"], error ? errorId : hint ? hintId : undefined]
      .filter(Boolean)
      .join(" ") || undefined;

    useImperativeHandle(forwardedRef, () => inputRef.current as HTMLInputElement);

    const updateValue = (nextValue: string) => {
      const normalized = digitsOnly(nextValue, safeLength);
      if (value === undefined) setInternalValue(normalized);
      onValueChange?.(normalized);
      if (normalized.length === safeLength && normalized !== currentValue) onComplete?.(normalized);
    };

    return (
      <div className={["w-full", className].filter(Boolean).join(" ")}>
        {label ? (
          <label className="mb-2 block text-sm font-[650] text-[var(--text)]" htmlFor={inputId}>
            {label}{required ? <span aria-hidden="true"> *</span> : null}
          </label>
        ) : null}

        <div
          className="relative grid w-full max-w-[25rem] grid-cols-[repeat(var(--verification-code-length),minmax(0,1fr))] gap-2"
          style={{ "--verification-code-length": safeLength } as CSSProperties}
          onClick={() => inputRef.current?.focus()}
        >
          <input
            {...props}
            ref={inputRef}
            id={inputId}
            className="absolute inset-0 z-10 size-full cursor-text opacity-0 disabled:cursor-not-allowed"
            type="text"
            inputMode="numeric"
            autoComplete="one-time-code"
            pattern={`[0-9]{${safeLength}}`}
            maxLength={safeLength}
            value={currentValue}
            disabled={disabled}
            required={required}
            aria-describedby={describedBy}
            aria-invalid={error ? true : props["aria-invalid"]}
            onChange={(event) => { updateValue(event.currentTarget.value); setCaret(event.currentTarget.selectionStart); }}
            onSelect={(event) => { setCaret(event.currentTarget.selectionStart); props.onSelect?.(event); }}
            onFocus={(event) => {
              setFocused(true);
              onFocus?.(event);
            }}
            onBlur={(event) => {
              setFocused(false);
              onBlur?.(event);
            }}
          />

          {Array.from({ length: safeLength }, (_, index) => {
            const digit = currentValue[index];
            const active = focused && index === activeIndex;
            return (
              <motion.span
                aria-hidden="true"
                className={[
                  "relative grid aspect-square min-h-12 min-w-0 place-items-center overflow-hidden rounded-[18px] border text-xl font-[650] tabular-nums text-[var(--text)] transition-[border-color,background-color] duration-[var(--duration-standard)] ease-[var(--ease-standard)]",
                  active
                    ? "border-[var(--focus)] bg-[color-mix(in_srgb,var(--surface-muted)_78%,var(--primary))]"
                    : error
                      ? "border-[var(--danger-surface-foreground)] bg-[var(--surface-muted)]"
                      : "border-[var(--border)] bg-[var(--surface-muted)]",
                  disabled ? "opacity-[0.48]" : "",
                ].filter(Boolean).join(" ")}
                key={index}
              >
                <AnimatePresence initial={false} mode="popLayout">
                  {digit ? (
                    <motion.span
                      key={digit}
                      initial={reduceMotion ? { opacity: 0 } : { opacity: 0, y: 7, filter: "blur(3px)" }}
                      animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
                      exit={reduceMotion ? { opacity: 0 } : { opacity: 0, y: -7, filter: "blur(3px)" }}
                      transition={reduceMotion ? { duration: 0 } : {
                        duration: motionTokens.duration.standard,
                        ease: motionTokens.ease.standard,
                      }}
                    >
                      {digit}
                    </motion.span>
                  ) : active ? (
                    <motion.span
                      className="h-5 w-px bg-[var(--text)]"
                      initial={{ opacity: 0 }}
                      animate={{ opacity: [0, 1, 1, 0] }}
                      transition={reduceMotion ? { duration: 0 } : { duration: 1.1, repeat: Infinity, times: [0, 0.1, 0.55, 1] }}
                    />
                  ) : null}
                </AnimatePresence>
              </motion.span>
            );
          })}
        </div>

        {error ? (
          <p className="mt-2 text-xs leading-5 text-[var(--danger-surface-foreground)]" id={errorId} role="alert">
            {error}
          </p>
        ) : hint ? (
          <p className="mt-2 text-xs leading-5 text-[var(--text-secondary)]" id={hintId}>
            {hint}
          </p>
        ) : null}
      </div>
    );
  },
);
